<?php
declare(strict_types=1);
require_once __DIR__ . '/lib.php';
require_admin();
$groups = db()->query('SELECT g.*, d.name AS device_name FROM facebook_groups g JOIN devices d ON d.id=g.device_id ORDER BY g.updated_at DESC')->fetchAll();
$devices = db()->query('SELECT name, last_sync_at FROM devices ORDER BY last_sync_at DESC')->fetchAll();
?>
<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>DUC TOOL Group Manager</title><link rel="stylesheet" href="assets/style.css"></head><body><header><div><b>DUC TOOL</b><span>Facebook Group Manager</span></div><a href="logout.php">Đăng xuất</a></header><main><section class="stats"><article><strong><?= count($groups) ?></strong><span>Tổng nhóm</span></article><article><strong><?= count($devices) ?></strong><span>Thiết bị</span></article><article><strong><?= count(array_filter($groups, fn($g) => (int)$g['enabled'] === 1)) ?></strong><span>Đang chọn</span></article></section><section class="panel"><div class="panel-head"><h1>Danh sách nhóm</h1><input id="search" type="search" placeholder="Tìm tên, ID hoặc thiết bị…"></div><div class="table-wrap"><table><thead><tr><th>Ảnh</th><th>Tên nhóm</th><th>ID</th><th>Thiết bị</th><th>Cập nhật</th></tr></thead><tbody id="rows"><?php foreach ($groups as $g): ?><tr data-search="<?= htmlspecialchars(strtolower($g['group_name'].' '.$g['facebook_id'].' '.$g['device_name'])) ?>"><td><?php if ($g['image_url']): ?><img src="<?= htmlspecialchars($g['image_url']) ?>" alt=""><?php endif; ?></td><td><a href="<?= htmlspecialchars($g['group_url']) ?>" target="_blank" rel="noreferrer"><?= htmlspecialchars($g['group_name']) ?></a></td><td><?= htmlspecialchars($g['facebook_id'] ?: '—') ?></td><td><?= htmlspecialchars($g['device_name']) ?></td><td><?= htmlspecialchars($g['updated_at']) ?></td></tr><?php endforeach; ?></tbody></table></div></section></main><script src="assets/app.js"></script></body></html>
